import subprocess, os, tempfile, json
EXE="/workspace/executable"
def run(args,cwd=None, env=None):
    e=dict(os.environ)
    if env: e.update(env)
    r=subprocess.run([EXE]+args, cwd=cwd, capture_output=True, text=True, env=e)
    print("ARGS",args,"CODE",r.returncode)
    print("OUT",repr(r.stdout)); print("ERR",repr(r.stderr)); return r
def mk(files):
    d=tempfile.mkdtemp()
    for f,c in files.items():
        p=os.path.join(d,f)
        if c is None: os.makedirs(p,exist_ok=True)
        else:
            os.makedirs(os.path.dirname(p),exist_ok=True); open(p,"w").write(c)
    return d

d=mk({"a.txt":"AAA","b.txt":"BBB"})
dump={"date":"2020-01-01 00:00:00","operations":[{"source":"a.txt","target":"x.txt"},{"source":"b.txt","target":"y.txt"}]}
open(os.path.join(d,"dump.json"),"w").write(json.dumps(dump))
run(["from-file","dump.json"],cwd=d)
run(["from-file","-f","--no-dump","dump.json"],cwd=d)
