{"command":"python3 - << 'PY'
import subprocess,os,tempfile
EXE="/workspace/executable"
def run(args,cwd):
    r=subprocess.run([EXE]+args,cwd=cwd,capture_output=True,text=True); print(r.returncode,repr(r.stdout),repr(r.stderr))
d=tempfile.mkdtemp()
for n in ["a-z.txt","b-z.txt","y-a.txt","z-a.txt"] : open(os.path.join(d,n),"w").write("x")
for i in range(5): run(["regex",r"^[^-]+-","","a-z.txt","b-z.txt","y-a.txt","z-a.txt"],cwd=d)
# Member ordering crossover: Sources with target same but source lex order vs something else (length/depth)
# e.g. sources sub/a1.txt and a2.txt in diff dirs target same only if parent same, so sources all same dir for target equality generally (except replacements absolute target dir). Use replacements /tmp/x absolute makes diff parents target equal. Existing target /tmp/x.txt may not exist.
d2=tempfile.mkdtemp(); os.makedirs(os.path.join(d2,"sub"))
for n in ["sub/zz.txt","aa.txt","mm.txt"]: open(os.path.join(d2,n),"w").write("x")
for i in range(3): run(["regex",r"^.*$","/tmp/target","sub/zz.txt","aa.txt","mm.txt"],cwd=d2)
# Groups with absolute targets crossing in source vs target use filename designator pattern:
# files in dirs: A source aa.txt target suffix? use regex ^.*-(.*) replace ${1} only on filename; sources a-z etc already.
PY"}

