EXE="/workspace/executable"
def run(args,cwd,env=None):
 e=dict(os.environ); e.update(env or {})
 r=subprocess.run([EXE]+args,cwd=cwd,capture_output=True,text=True,env=e); print(args,env,r.returncode,repr(r.stdout),repr(r.stderr))
# backup edge from-file
def ff(ops,args=["-f","-b","--no-dump"]):
