for src in ["","..",".","/","a/..","a/."]:
 ff([{"source":src,"target":"x.txt"}])
# rename edge from-file invalid source silents
for src in ["","..",".","/"]:
 ff([{"source":src,"target":"x.txt"}],args=["-s","-f","--no-dump"])
# TZ environment dump
