{"command":"python3 - << 'PY'
import subprocess,os,tempfile,collections
EXE="/workspace/executable"
d=tempfile.mkdtemp(); names=[f"a{i}.txt" for i in range(20)]
for n in names: open(os.path.join(d,n),"w").write("x")
for env in [{},{"RAYON_NUM_THREADS":"1"},{"RAYON_NUM_THREADS":"2"}]:
    outs=collections.Counter()
    for i in range(20):
        r=subprocess.run([EXE,"regex","a","A"]+names,cwd=d,capture_output=True,text=True,env={**os.environ,**env})
        outs[r.stdout]+=1
    print("env",env,"distinct",len(outs))
    for out,c in list(outs.items())[:3]: print(c, out.splitlines()[1:6])
PY"}

