use clap::{Parser, Subcommand, ValueEnum, Args};
/// RnR is a command-line tool to rename multiple files and directories that
/// supports regular expressions
///
#[derive(Parser)]
#[command(version, arg_required_else_help = true)]
struct Cli { #[command(subcommand)] command: Commands }
#[derive(Subcommand)]
enum Commands {
    /// Rename files and directories using a regular expression
    #[command(arg_required_else_help = true)]
    Regex(RegexArgs),
    /// Read operations from a dump file
    #[command(arg_required_else_help = true)]
    FromFile(FromFileArgs),
    /// Replace file name UTF-8 chars with ASCII chars representation
    #[command(arg_required_else_help = true)]
    ToAscii(ToAsciiArgs),
}
#[derive(Clone, Debug, ValueEnum)]
enum ColorMode { Always, Never, Auto }
#[derive(Clone, Debug, ValueEnum)]
enum Transform { Upper, Lower, Ascii }
#[derive(Args, Debug)]
struct Common {
    /// Only show what would be done (default mode)
    #[arg(short = 'n', long, conflicts_with = "force")]
    dry_run: bool,
    /// Make actual changes to files
    #[arg(short = 'f', long)]
    force: bool,
    /// Generate file backups before renaming
    #[arg(short = 'b', long)]
    backup: bool,
    /// Do not print any information
    #[arg(short = 's', long)]
    silent: bool,
    /// Set color output mode
    #[arg(long, value_enum, default_value_t = ColorMode::Auto)]
    color: ColorMode,
    /// Force dumping operations into a file even in dry-run mode
    #[arg(long, conflicts_with = "no_dump")]
    dump: bool,
    /// Set the dump file prefix
    #[arg(long, default_value = "rnr-", conflicts_with = "no_dump")]
    dump_prefix: String,
    /// Do not dump operations into a file
    #[arg(long)]
    no_dump: bool,
}
#[derive(Args, Debug)]
struct RegexArgs {
    #[command(flatten)] common: Common,
    /// Limit of replacements, all matches if set to 0
    #[arg(short = 'l', long = "replace-limit", value_name = "LIMIT")]
    replace_limit: Option<usize>,
    /// Apply a transformation to replacements including captured groups
    #[arg(short = 't', long = "replace-transform", value_enum)]
    replace_transform: Option<Transform>,
    /// Rename matching directories
    #[arg(short = 'D', long)]
    include_dirs: bool,
    /// Recursive mode
    #[arg(short = 'r', long)]
    recursive: bool,
    /// Set max depth in recursive mode
    #[arg(short = 'd', long, value_name = "LEVEL", requires = "recursive")]
    max_depth: Option<usize>,
    /// Include hidden files and directories
    #[arg(short = 'x', long, requires = "recursive")]
    hidden: bool,
    /// Expression to match (can be a regex)
    expression: String,
    /// Expression replacement (use single quotes for capture groups)
    replacement: String,
    /// Target paths
    #[arg(value_name = "PATH(S)")]
    paths: Vec<String>,
}
#[derive(Args, Debug)]
struct FromFileArgs {
    #[command(flatten)] common: Common,
    /// Undo the operations from the dump file
    #[arg(short = 'u', long)]
    undo: bool,
    dumpfile: String,
}
#[derive(Args, Debug)]
struct ToAsciiArgs {
    #[command(flatten)] common: Common,
    /// Rename matching directories
    #[arg(short = 'D', long)]
    include_dirs: bool,
    /// Recursive mode
    #[arg(short = 'r', long)]
    recursive: bool,
    /// Set max depth in recursive mode
    #[arg(short = 'd', long, value_name = "LEVEL", requires = "recursive")]
    max_depth: Option<usize>,
    /// Include hidden files and directories
    #[arg(short = 'x', long, requires = "recursive")]
    hidden: bool,
    /// Target paths
    #[arg(value_name = "PATH(S)")]
    paths: Vec<String>,
}
fn main(){ let cli=Cli::parse(); println!("{:?}",cli.command); }
impl std::fmt::Debug for Commands { fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{ write!(f,"cmd") } }
RS
