fn grouped(a:&str,b:&str,rev:bool){
 let seq=if rev {diff::chars(b,a)} else {diff::chars(a,b)};
 // group consecutive same variant, but for rev left=insert, right=delete
 let mut out:Vec<(String,String)>=Vec::new(); let mut cur_kind=""; let mut cur=String::new();
 let mut flush=|k:&str,s:&String,out:&mut Vec<(String,String)>|{ if !s.is_empty(){out.push((k.to_string(),s.clone()));}};
 for r in seq {
   let (k,s)=match r {diff::Result::Left(c)=>("L",c.to_string()),diff::Result::Right(c)=>("R",c.to_string()),diff::Result::Both(c,_)=>("B",c.to_string())};
   if k!=cur_kind { flush(cur_kind,&cur,&mut out); cur_kind=k; cur=String::new(); }
   cur.push_str(&s);
 }
 flush(cur_kind,&cur,&mut out);
 println!("rev={} {} -> {} {:?}",rev,a,b,out);
}
fn main(){for (a,b) in [("hello-world.txt","hello-there.txt"),("abc","acb"),("acb","abc"),("ab","ba"),("xyzabc","abcxyz"),("aaaa.txt","aa.txt"),("aaaaabaaaaa","aaabaaa"),("kitten","sitting"),("abcabc","bcabca"),("sunday","saturday"),("flaw","lawn"),("gumbo","gambol"),("book","back"),("aab","baa"),("abcd","badc")] {grouped(a,b,true);} }
