import difflib
cases=[("hello-world.txt","hello-there.txt"),("abc","acb"),("acb","abc"),("ab","ba"),("xyzabc","abcxyz"),("aaaa.txt","aa.txt"),("aaaaabaaaaa","aaabaaa"),("kitten","sitting"),("abcabc","bcabca"),("sunday","saturday"),("flaw","lawn"),("gumbo","gambol"),("book","back"),("aab","baa"),("abcd","badc"),("aaaa","aa"),("aa","aaaa"),("abcdef","abxcyd"),("123456","456123"),("abababab","babababa"),("e\u0301.txt","e.txt")]
for a,b in cases:
 sm=difflib.SequenceMatcher(a=a,b=b,autojunk=False)
 segs=[]
 for tag,i1,i2,j1,j2 in sm.get_opcodes():
  if tag=='equal': segs.append(('G',b[j1:j2]))
  elif tag in ('insert','replace'): segs.append(('R',b[j1:j2]))
  elif tag=='delete': pass
 print(a,b,segs,sm.get_opcodes())
