use std::io::{self, BufRead};
fn grouped(src:&str,tgt:&str){
 let seq=diff::chars(tgt,src);
 let mut out=Vec::new();
 let mut kind=' ';
 let mut cur=String::new();
 for r in seq {
  let (k,c)=match r {diff::Result::Left(c)=>('R',c),diff::Result::Right(c)=>('D',c),diff::Result::Both(c,_)=>('G',c)};
  if k!=kind { if kind!=' ' && kind!='D' && !cur.is_empty(){out.push(format!("{}{}",kind,cur));} kind=k; cur=String::new(); }
  cur.push(c);
 }
 if kind!=' ' && kind!='D' && !cur.is_empty(){out.push(format!("{}{}",kind,cur));}
 println!("{}",out.join("|"));
}
fn main(){let stdin=io::stdin(); for line in stdin.lock().lines(){let line=line.unwrap(); let mut p=line.split('\t'); let a=p.next().unwrap_or(""); let b=p.next().unwrap_or(""); grouped(a,b);}}
