import subprocess,os,tempfile,json,re,random
EXE="/workspace/executable"; CAND="/tmp/colortest/target/debug/colortest"
ansi=re.compile(r'\x1b\[([0-9;]*)m([^\x1b]*)\x1b\[0m')
def ref_segments(src,tgt):
    d=tempfile.mkdtemp(); open(os.path.join(d,"d.json"),"w").write(json.dumps({"date":"x","operations":[{"source":src,"target":tgt}]}))
    r=subprocess.run([EXE,"from-file","--color","always","d.json"],cwd=d,capture_output=True,text=True)
    line=r.stdout.splitlines()[1]; tgtpart=line.split(" -> ",1)[1]
    return [('G' if code=='32' else 'R',text) for code,text in ansi.findall(tgtpart)]
random.seed(1); cases=[("hello-world.txt","hello-there.txt"),("abc","acb"),("acb","abc"),("ab","ba"),("xyzabc","abcxyz"),("aaaa.txt","aa.txt"),("aaaaabaaaaa","aaabaaa"),("kitten","sitting"),("abcabc","bcabca"),("sunday","saturday"),("flaw","lawn"),("gumbo","gambol"),("book","back"),("aab","baa"),("abcd","badc")]
for _ in range(80):
    a=''.join(random.choice("abc") for _ in range(random.randint(1,10))); b=''.join(random.choice("abc") for _ in range(random.randint(1,10))); cases.append((a,b))
cases=list(dict.fromkeys(cases))
inp='\n'.join(a+'\t'+b for a,b in cases)
outs=subprocess.run([CAND],input=inp,capture_output=True,text=True).stdout.splitlines()
bad=0
for (src,tgt),o in zip(cases,outs):
    cand=[] if not o else [(part[0],part[1:]) for part in o.split('|')]
    r=ref_segments(src,tgt)
    if r!=cand:
        bad+=1; print("MISMATCH",src,tgt,"ref",r,"cand",cand)
print("bad",bad,"of",len(cases))
PY"}

