EXE="/workspace/executable"
start=time.time(); total=0
for batch_start in range(0x80,0x80+500*5,500):
 d=tempfile.mkdtemp(); names=[]
 for cp in range(batch_start,batch_start+500):
  if 0xD800<=cp<=0xDFFF: continue
  ch=chr(cp); name=f"u{cp}X{ch}Y.txt"; names.append(name)
  try: open(os.path.join(d,name),"w").write("x")
  except Exception as e: print("create fail",cp,e)
 r=subprocess.run([EXE,"to-ascii","--dump"]+names,cwd=d,capture_output=True,text=True)
 dumps=[f for f in os.listdir(d) if f.startswith("rnr-")]
 print(batch_start,r.returncode,len(dumps),r.stderr[:200], "time",time.time()-start)
 if dumps:
  data=json.load(open(os.path.join(d,dumps[0])))
  print(data["operations"][:5]); total+=len(data["operations"])
print("total ops",total)
