    CannotRename(PathBuf, PathBuf, io::Error),
    ConflictWithExistingPath(PathBuf, PathBuf),
    FilesWithSameName(String),
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AppError::BadExpression(e) => {
                write!(f, "Bad expression provided\n\n{}", color::red(&e.to_string()))
            }
            AppError::CannotOpenReadFile(path) => {
                write!(
