            AppError::CannotCreateFile(path) => {
                write!(
                    f,
                    "Cannot create file {}",
                    color::red(&path.display().to_string())
                )
            }
            AppError::CannotCreateBackup(path) => {
                write!(
                    f,
                    "Cannot create a backup of {}",
                    color::red(&path.display().to_string())
                )
            }
            AppError::CannotRename(source, target, e) => {
                write!(
                    f,
                    "Cannot rename {}",
                    color::red(&format!(
                        "{} -> {}\n{}",
                        source.display(),
                        target.display(),
                        e
                    ))
                )
            }
            AppError::ConflictWithExistingPath(source, target) => {
                write!(
                    f,
                    "Conflict with existing path {}",
                    color::red(&format!("{} -> {}", source.display(), target.display()))
                )
            }
            AppError::FilesWithSameName(collisions) => {
                write!(f, "Files will have the same name\n{}", color::red(collisions))
            }
        }
    }
}

impl std::error::Error for AppError {}

pub type AppResult<T> = Result<T, AppError>;
