use crate::errors::{AppError, AppResult};
use std::fs;
use std::path::{Path, PathBuf};

pub fn path_exists(path: &Path) -> bool {
    path.exists() || path.is_symlink()
}

pub fn create_backup(path: &Path) -> AppResult<PathBuf> {
    let file_name = path.file_name().unwrap().to_string_lossy().into_owned();
    let mut backup_path = path.with_file_name(format!("{file_name}.bk"));
    let mut counter = 1usize;
    while path_exists(&backup_path) {
        backup_path = path.with_file_name(format!("{file_name}.bk.{counter}"));
        counter += 1;
    }
    fs::copy(path, &backup_path)
        .map_err(|_| AppError::CannotCreateBackup(path.to_path_buf()))?;
    Ok(backup_path)
}
