use crate::color;
use crate::operations::Operation;
use std::path::Path;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DiffKind {
    Common,
    Added,
    Removed,
}

fn diff_segments(source: &str, target: &str) -> Vec<(DiffKind, String)> {
    let source_chars: Vec<char> = source.chars().collect();
    let target_chars: Vec<char> = target.chars().collect();
    let source_len = source_chars.len();
    let target_len = target_chars.len();
    let mut lengths = vec![vec![0usize; target_len + 1]; source_len + 1];
    for i in (0..source_len).rev() {
        for j in (0..target_len).rev() {
            lengths[i][j] = if source_chars[i] == target_chars[j] {
                lengths[i + 1][j + 1] + 1
            } else {
                lengths[i + 1][j].max(lengths[i][j + 1])
            };
        }
    }

    let mut raw: Vec<(DiffKind, char)> = Vec::new();
    let mut i = 0usize;
    let mut j = 0usize;
    while i < source_len && j < target_len {
        if source_chars[i] == target_chars[j] {
            raw.push((DiffKind::Common, target_chars[j]));
            i += 1;
            j += 1;
        } else if lengths[i][j + 1] >= lengths[i + 1][j] {
            raw.push((DiffKind::Added, target_chars[j]));
            j += 1;
        } else {
            raw.push((DiffKind::Removed, source_chars[i]));
            i += 1;
        }
    }
    while j < target_len {
        raw.push((DiffKind::Added, target_chars[j]));
        j += 1;
    }
    while i < source_len {
        raw.push((DiffKind::Removed, source_chars[i]));
        i += 1;
    }

    let mut segments: Vec<(DiffKind, String)> = Vec::new();
    for (kind, ch) in raw {
        if let Some((last_kind, text)) = segments.last_mut() {
            if *last_kind == kind {
                text.push(ch);
                continue;
            }
        }
        segments.push((kind, ch.to_string()));
    }
    segments
}

#[derive(Debug, Clone)]
pub struct Output {
    silent: bool,
}

impl Output {
    pub fn new(silent: bool) -> Self {
        Self { silent }
    }

    pub fn print_dry_run(&self) {
        if !self.silent {
            println!("{}", color::bold("This is a DRY-RUN"));
        }
    }

    pub fn print_backup(&self, source: &Path, backup: &Path) {
        if !self.silent {
            println!(
                "{} Backup created - {}",
                color::bold("Info: "),
                color::grey(&format!("{} -> {}", source.display(), backup.display()))
            );
        }
    }

    pub fn print_operation(&self, operation: &Operation) {
        if self.silent {
            return;
        }
        let source_parent = operation.source.parent().unwrap();
        let source_file_name = operation.source.file_name().unwrap();
        let target_parent = operation.target.parent().unwrap();
        let target_file_name = operation.target.file_name().unwrap();

        let mut source = String::new();
        if !source_parent.as_os_str().is_empty() {
            source.push_str(&color::grey(&format!("{}/", source_parent.display())));
        }
        source.push_str(&color::grey(&source_file_name.to_string_lossy()));

        let mut target = String::new();
        if !target_parent.as_os_str().is_empty() {
            target.push_str(&color::green(&format!("{}/", target_parent.display())));
        }
        for (kind, text) in diff_segments(
            &source_file_name.to_string_lossy(),
            &target_file_name.to_string_lossy(),
        ) {
            match kind {
                DiffKind::Common => target.push_str(&color::green(&text)),
                DiffKind::Added => target.push_str(&color::bold_red(&text)),
                DiffKind::Removed => {}
            }
        }
        println!("{source} -> {target}");
    }
}
