use crate::errors::{AppError, AppResult};
use crate::fileutils;
use crate::operations::Operations;
use crate::output::Output;
use crate::solver::{AsciiSolver, RegexSolver};
use std::fs;
use std::mem;

#[derive(Debug, Clone)]
pub struct Renamer {
    pub force: bool,
    pub backup: bool,
    pub dump: bool,
    pub dump_prefix: String,
    pub no_dump: bool,
    output: Output,
}

impl Renamer {
    pub fn new(
        force: bool,
        backup: bool,
        silent: bool,
        dump: bool,
        dump_prefix: String,
        no_dump: bool,
    ) -> Self {
        Self {
            force,
            backup,
            dump,
            dump_prefix,
            no_dump,
            output: Output::new(silent),
        }
    }

    pub fn rename_with_regex(&self, solver: &RegexSolver) -> AppResult<()> {
        if !self.force {
            self.output.print_dry_run();
        }
        let mut operations = solver.get_operations()?;
        self.process(&mut operations)
    }

    pub fn rename_to_ascii(&self, solver: &AsciiSolver) -> AppResult<()> {
        if !self.force {
            self.output.print_dry_run();
        }
        let mut operations = solver.get_operations()?;
        self.process(&mut operations)
    }

    pub fn rename_from_file(&self, dumpfile: &str, undo: bool) -> AppResult<()> {
        if !self.force {
            self.output.print_dry_run();
        }
        let mut operations = Operations::from_file(dumpfile)?;
        if undo {
            operations.operations.reverse();
            for operation in &mut operations.operations {
                mem::swap(&mut operation.source, &mut operation.target);
            }
        }
        self.process(&mut operations)
    }

    fn process(&self, operations: &mut Operations) -> AppResult<()> {
        if !self.no_dump && (self.force || self.dump) {
            operations.dump(&self.dump_prefix)?;
        }
        for operation in &operations.operations {
            if self.force {
                if self.backup && !operation.source.is_dir() {
                    let backup_path = fileutils::create_backup(&operation.source)?;
                    self.output.print_backup(&operation.source, &backup_path);
                }
                fs::rename(&operation.source, &operation.target).map_err(|e| {
                    AppError::CannotRename(
                        operation.source.clone(),
                        operation.target.clone(),
                        e,
                    )
                })?;
            }
