from difflib import SequenceMatcher
DATA=json.load(open("/tmp/diff_dataset.json"))
def group(seq):
 segs=[];curk=None;cur=''
 for k,ch in seq:
  if k!=curk:
   if curk in ('G','R') and cur:segs.append((curk,cur))
   curk=k;cur=''
  cur+=ch
 if curk in ('G','R') and cur:segs.append((curk,cur))
 return segs

def suffix_walk(a,b,tie_insert=True,match_equal_first=True):
 n=len(a);m=len(b); dp=[[0]*(m+1) for _ in range(n+1)]
 for i in range(n-1,-1,-1):
  for j in range(m-1,-1,-1): dp[i][j]=dp[i+1][j+1]+1 if a[i]==b[j] else max(dp[i+1][j],dp[i][j+1])
 seq=[];i=j=0
 while i<n and j<m:
  if a[i]==b[j] and match_equal_first: seq.append(('G',b[j]));i+=1;j+=1
  elif dp[i][j+1]>dp[i+1][j] or (tie_insert and dp[i][j+1]==dp[i+1][j]): seq.append(('R',b[j]));j+=1
  else: seq.append(('D',a[i]));i+=1
 while j<m:seq.append(('R',b[j]));j+=1
 while i<n:seq.append(('D',a[i]));i+=1
 return group(seq)

def prefix_backtrack(a,b,tie='delete',equal_first=True):
 n=len(a);m=len(b); dp=[[0]*(m+1) for _ in range(n+1)]
 for i in range(1,n+1):
  for j in range(1,m+1): dp[i][j]=dp[i-1][j-1]+1 if a[i-1]==b[j-1] else max(dp[i-1][j],dp[i][j-1])
 seq=[];i=n;j=m
 while i>0 and j>0:
  if a[i-1]==b[j-1] and equal_first:
   seq.append(('G',b[j-1]));i-=1;j-=1
  elif dp[i-1][j]>dp[i][j-1] or (tie=='delete' and dp[i-1][j]==dp[i][j-1]):
   seq.append(('D',a[i-1]));i-=1
  elif dp[i][j-1]>dp[i-1][j] or (tie=='insert' and dp[i-1][j]==dp[i][j-1]):
   seq.append(('R',b[j-1]));j-=1
  elif a[i-1]==b[j-1]:
   seq.append(('G',b[j-1]));i-=1;j-=1
  else: break
 while j>0:seq.append(('R',b[j-1]));j-=1
 while i>0:seq.append(('D',a[i-1]));i-=1
 return group(reversed(seq))

def prefix_backtrack_condorder(a,b,mode):
 # Walk based on equality of dp values like diff crate backtrack (without prefix/suffix strip)
 n=len(a);m=len(b); dp=[[0]*(m+1) for _ in range(n+1)]
 for i in range(1,n+1):
  for j in range(1,m+1): dp[i][j]=dp[i-1][j-1]+1 if a[i-1]==b[j-1] else max(dp[i-1][j],dp[i][j-1])
 seq=[];i=n;j=m
 while True:
  if mode=='diffcrate':
   if j>0 and (i==0 or dp[i][j]==dp[i][j-1]): seq.append(('R',b[j-1]));j-=1
   elif i>0 and (j==0 or dp[i][j]==dp[i-1][j]): seq.append(('D',a[i-1]));i-=1
   elif i>0 and j>0: seq.append(('G',b[j-1]));i-=1;j-=1
