 if curk in ('G','R') and cur:segs.append((curk,cur))
 return segs
def lcs_row(a,b):
 # lengths of LCS(a, b[:j]) for j=0..len(b)
 prev=[0]*(len(b)+1)
 for ca in a:
  cur=[0]
  for j,cb in enumerate(b,1):cur.append(prev[j-1]+1 if ca==cb else max(prev[j],cur[-1]))
  prev=cur
 return prev

def hirsch(a,b,tie='min',base_first=True,split='source'):
 # returns seq tokens ('G' char from b, 'R' b char, 'D' a char)
 if not a:return [('R',c) for c in b]
 if not b:return [('D',c) for c in a]
 if split=='longer' and len(b)>len(a):
  # split b symmetric by swapping roles and token mapping
  swapped=hirsch(b,a,tie,base_first,split)
