use crate::color;
use crate::operations::Operation;
use std::ffi::OsStr;
use std::path::Path;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DiffKind {
    Common,
    Added,
    Removed,
}

// Build the table of longest-common-subsequence lengths for every pair of
// prefixes of the source and target file names.  Keeping the whole table
// makes the backtracking step straightforward: each move can be checked
// against the lengths of the neighboring prefixes.
fn lcs_lengths(source_chars: &[char], target_chars: &[char]) -> Vec<Vec<usize>> {
    let source_len = source_chars.len();
    let target_len = target_chars.len();
    let mut lengths = vec![vec![0usize; target_len + 1]; source_len + 1];
    for i in 1..=source_len {
        for j in 1..=target_len {
            lengths[i][j] = if source_chars[i - 1] == target_chars[j - 1] {
                lengths[i - 1][j - 1] + 1
            } else {
                lengths[i - 1][j].max(lengths[i][j - 1])
            };
        }
    }
    lengths
}

// Group a character-by-character diff into runs of the same kind.  Removed
// runs are retained at this stage because they act as separators between
// two common runs in the coloured target name.
fn group_diff_segments(raw: Vec<(DiffKind, char)>) -> Vec<(DiffKind, String)> {
    let mut segments: Vec<(DiffKind, String)> = Vec::new();
    for (kind, ch) in raw {
        if let Some((last_kind, text)) = segments.last_mut() {
            if *last_kind == kind {
                text.push(ch);
                continue;
            }
        }
        segments.push((kind, ch.to_string()));
    }
    segments
}

fn diff_segments(source: &str, target: &str) -> Vec<(DiffKind, String)> {
    let source_chars: Vec<char> = source.chars().collect();
    let target_chars: Vec<char> = target.chars().collect();
    let source_len = source_chars.len();
    let target_len = target_chars.len();
    let lengths = lcs_lengths(&source_chars, &target_chars);

    let mut raw = Vec::new();
    let mut i = source_len;
    let mut j = target_len;
    loop {
        if i > 0 && (j == 0 || lengths[i][j] == lengths[i - 1][j]) {
            raw.push((DiffKind::Removed, source_chars[i - 1]));
            i -= 1;
        } else if j > 0 && (i == 0 || lengths[i][j] == lengths[i][j - 1]) {
            raw.push((DiffKind::Added, target_chars[j - 1]));
            j -= 1;
        } else if i > 0 && j > 0 {
            raw.push((DiffKind::Common, target_chars[j - 1]));
            i -= 1;
            j -= 1;
        } else {
            break;
        }
    }
    raw.reverse();
    group_diff_segments(raw)
}

fn format_parent(parent: &Path, colour: fn(&str) -> String) -> String {
    if parent.as_os_str().is_empty() {
        String::new()
    } else {
        colour(&format!("{}/", parent.display()))
    }
}

fn format_target_file_name(source_file_name: &OsStr, target_file_name: &OsStr) -> String {
    let source = source_file_name.to_string_lossy();
    let target = target_file_name.to_string_lossy();
    let mut formatted = String::new();
    for (kind, text) in diff_segments(&source, &target) {
        match kind {
            DiffKind::Common => formatted.push_str(&color::green(&text)),
            DiffKind::Added => formatted.push_str(&color::bold_red(&text)),
            DiffKind::Removed => {}
        }
    }
    formatted
}

#[derive(Debug, Clone)]
pub struct Output {
    silent: bool,
}

impl Output {
    pub fn new(silent: bool) -> Self {
        Self { silent }
    }

    pub fn print_dry_run(&self) {
        if !self.silent {
            println!("{}", color::bold("This is a DRY-RUN"));
        }
    }

    pub fn print_backup(&self, source: &Path, backup: &Path) {
        if !self.silent {
            println!(
                "{} Backup created - {}",
                color::bold("Info: "),
                color::grey(&format!("{} -> {}", source.display(), backup.display()))
            );
        }
    }

    pub fn print_operation(&self, operation: &Operation) {
        if self.silent {
            return;
        }
        let src_dir = operation.source.parent().unwrap();
        let sname = operation.source.file_name().unwrap();
        let tgt_dir = operation.target.parent().unwrap();
        let tname = operation.target.file_name().unwrap();

        let mut source = format_parent(src_dir, color::grey);
        source.push_str(&color::grey(&sname.to_string_lossy()));

        let mut target = format_parent(tgt_dir, color::green);
        target.push_str(&format_target_file_name(sname, tname));

        println!("{source} -> {target}");
    }
}
