use crate::errors::{AppError, AppResult};
use std::fs;
use std::path::{Path, PathBuf};

pub fn path_exists(path: &Path) -> bool {
    path.exists() || path.is_symlink()
}

pub fn rename_path(source: &Path, target: &Path) -> AppResult<()> {
    fs::rename(source, target).map_err(|e| {
        AppError::CannotRename(source.to_path_buf(), target.to_path_buf(), e)
    })
}

fn copy_for_backup(source_path: &Path, backup_path: &Path) -> AppResult<()> {
    fs::copy(source_path, backup_path)
        .map_err(|_| AppError::CannotCreateBackup(source_path.to_path_buf()))?;
    Ok(())
}

fn backup_path_for(source_path: &Path, file_name: &str, counter: Option<usize>) -> PathBuf {
    match counter {
        None => source_path.with_file_name(format!("{file_name}.bk")),
        Some(counter) => {
            source_path.with_file_name(format!("{file_name}.bk.{counter}"))
        }
    }
}

pub fn create_backup(source_path: &Path) -> AppResult<PathBuf> {
    let original_file_name = source_path.file_name().unwrap().to_string_lossy().into_owned();
    let mut backup_path = backup_path_for(source_path, &original_file_name, None);
    let mut counter = 1usize;
    while path_exists(&backup_path) {
        backup_path = backup_path_for(source_path, &original_file_name, Some(counter));
        counter += 1;
    }
    copy_for_backup(source_path, &backup_path)?;
    Ok(backup_path)
}
