   curk=k;cur=''
  cur+=ch
 if curk in ('G','R') and cur:segs.append((curk,cur))
 return segs

def longest_block(a,b,tie):
 # DP common substring ending at i-1,j-1 lengths
 best=(0,0,0) # size, a_start,b_start
 prev=[0]*(len(b)+1)
 for i,ca in enumerate(a,1):
  cur=[0]
  for j,cb in enumerate(b,1):
   val=prev[j-1]+1 if ca==cb else 0;cur.append(val)
   if val:
    cand=(val,i-val,j-val)
