     best=cand
    elif cand[0]==best[0] and best[0]>0:
     # compare starts according tie
     keys={
      'source_then_target':lambda c:(c[1],c[2]),
      'target_then_source':lambda c:(c[2],c[1]),
      'source_end_then_target_end':lambda c:(c[1]+c[0],c[2]+c[0]),
